-- Enforce granular permissions at the RPC boundary. Screen navigation is not a security boundary.

create or replace function public.upsert_forecast_line(p_organization_id uuid,p_planning_version_id uuid,p_financial_period_id uuid,p_account_id uuid,p_amount_minor bigint,p_legal_entity_id uuid default null,p_branch_id uuid default null,p_department_id uuid default null,p_cost_center_id uuid default null,p_region_id uuid default null,p_product_id uuid default null,p_project_id uuid default null,p_notes text default null) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid; begin if auth.uid() is null or not public.has_org_permission(p_organization_id,'forecast.edit') then raise exception 'forbidden'; end if; if not exists(select 1 from public.planning_versions where id=p_planning_version_id and organization_id=p_organization_id and version_type='forecast' and status='draft') then raise exception 'forecast must be draft'; end if; if not exists(select 1 from public.financial_periods where id=p_financial_period_id and organization_id=p_organization_id) then raise exception 'invalid period'; end if; if not exists(select 1 from public.accounts where id=p_account_id and organization_id=p_organization_id) then raise exception 'invalid account'; end if; insert into public.forecast_lines(organization_id,planning_version_id,financial_period_id,account_id,amount_minor,legal_entity_id,branch_id,department_id,cost_center_id,region_id,product_id,project_id,notes,created_by) values(p_organization_id,p_planning_version_id,p_financial_period_id,p_account_id,p_amount_minor,p_legal_entity_id,p_branch_id,p_department_id,p_cost_center_id,p_region_id,p_product_id,p_project_id,p_notes,auth.uid()) on conflict(planning_version_id,financial_period_id,account_id,legal_entity_id,branch_id,department_id,cost_center_id,region_id,product_id,project_id) do update set amount_minor=excluded.amount_minor,notes=excluded.notes,updated_at=now() returning id into v_id; return v_id; end; $$;

create or replace function public.delete_forecast_line(p_organization_id uuid,p_forecast_line_id uuid) returns void language plpgsql security definer set search_path='' as $$ begin if auth.uid() is null or not public.has_org_permission(p_organization_id,'forecast.delete') then raise exception 'forbidden'; end if; delete from public.forecast_lines f where f.id=p_forecast_line_id and f.organization_id=p_organization_id and exists(select 1 from public.planning_versions v where v.id=f.planning_version_id and v.organization_id=p_organization_id and v.version_type='forecast' and v.status in ('draft','changes_requested')); end; $$;

create or replace function public.upsert_cash_forecast_line(p_organization_id uuid,p_planning_version_id uuid,p_financial_period_id uuid,p_cash_category text,p_amount_minor bigint,p_currency character default 'SAR',p_notes text default null) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid; begin if auth.uid() is null or not public.has_org_permission(p_organization_id,'cash.edit') then raise exception 'forbidden'; end if; if not exists(select 1 from public.planning_versions where id=p_planning_version_id and organization_id=p_organization_id and version_type='forecast' and status='draft') then raise exception 'forecast must be draft'; end if; if not exists(select 1 from public.financial_periods where id=p_financial_period_id and organization_id=p_organization_id) then raise exception 'invalid period'; end if; if p_cash_category not in ('opening_cash','cash_inflow','cash_outflow','financing','closing_cash') then raise exception 'invalid cash category'; end if; insert into public.cash_forecast_lines(organization_id,planning_version_id,financial_period_id,cash_category,amount_minor,currency,notes,created_by) values(p_organization_id,p_planning_version_id,p_financial_period_id,p_cash_category,p_amount_minor,p_currency,p_notes,auth.uid()) on conflict(planning_version_id,financial_period_id,cash_category) do update set amount_minor=excluded.amount_minor,currency=excluded.currency,notes=excluded.notes,updated_at=now() returning id into v_id; return v_id; end; $$;

create or replace function public.delete_cash_forecast_line(p_organization_id uuid,p_cash_forecast_line_id uuid) returns void language plpgsql security definer set search_path='' as $$ begin if auth.uid() is null or not public.has_org_permission(p_organization_id,'cash.delete') then raise exception 'forbidden'; end if; delete from public.cash_forecast_lines c where c.id=p_cash_forecast_line_id and c.organization_id=p_organization_id and exists(select 1 from public.planning_versions v where v.id=c.planning_version_id and v.status='draft'); end; $$;

create or replace function public.create_scenario(p_organization_id uuid,p_name text,p_description text default null,p_scenario_type text default 'what_if',p_base_version_id uuid default null) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid; begin if auth.uid() is null or not public.has_org_permission(p_organization_id,'scenario.create') then raise exception 'forbidden'; end if; if trim(coalesce(p_name,''))='' then raise exception 'scenario name required'; end if; if p_scenario_type not in ('what_if','upside','downside','stress') then raise exception 'invalid scenario type'; end if; if p_base_version_id is not null and not exists(select 1 from public.planning_versions v where v.id=p_base_version_id and v.organization_id=p_organization_id and v.version_type in ('budget','forecast')) then raise exception 'invalid base version'; end if; insert into public.planning_scenarios(organization_id,name,description,scenario_type,base_version_id,created_by) values(p_organization_id,trim(p_name),p_description,p_scenario_type,p_base_version_id,auth.uid()) returning id into v_id; return v_id; end; $$;

create or replace function public.upsert_scenario_adjustment(p_organization_id uuid,p_scenario_id uuid,p_financial_period_id uuid,p_account_id uuid,p_adjustment_type text,p_adjustment_value numeric,p_notes text default null) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid; begin if auth.uid() is null or not public.has_org_permission(p_organization_id,'scenario.edit') then raise exception 'forbidden'; end if; if not exists(select 1 from public.planning_scenarios s where s.id=p_scenario_id and s.organization_id=p_organization_id and s.status='draft') then raise exception 'scenario must be draft'; end if; if not exists(select 1 from public.financial_periods p where p.id=p_financial_period_id and p.organization_id=p_organization_id) then raise exception 'invalid period'; end if; if p_account_id is not null and not exists(select 1 from public.accounts a where a.id=p_account_id and a.organization_id=p_organization_id) then raise exception 'invalid account'; end if; if p_adjustment_type not in ('absolute','percentage') then raise exception 'invalid adjustment type'; end if; insert into public.scenario_adjustments(scenario_id,financial_period_id,account_id,adjustment_type,adjustment_value,notes) values(p_scenario_id,p_financial_period_id,p_account_id,p_adjustment_type,p_adjustment_value,p_notes) on conflict(scenario_id,financial_period_id,account_id) do update set adjustment_type=excluded.adjustment_type,adjustment_value=excluded.adjustment_value,notes=excluded.notes returning id into v_id; return v_id; end; $$;

-- Read RPCs use both screen-level and action-level grants.
create or replace function public.get_forecast_workspace(p_organization_id uuid,p_planning_version_id uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_version uuid; v_result jsonb; begin if auth.uid() is null or not public.has_org_permission(p_organization_id,'screen.forecast.view') or not public.has_org_permission(p_organization_id,'forecast.view') then raise exception 'Not authorized'; end if; if p_planning_version_id is not null then select id into v_version from public.planning_versions where id=p_planning_version_id and organization_id=p_organization_id and version_type='forecast'; if v_version is null then raise exception 'Forecast version not found'; end if; else select id into v_version from public.planning_versions where organization_id=p_organization_id and version_type='forecast' order by created_at desc limit 1; end if; select jsonb_build_object('version',(select to_jsonb(v) from public.planning_versions v where v.id=v_version),'periods',coalesce((select jsonb_agg(to_jsonb(p) order by p.period_start) from public.financial_periods p where p.organization_id=p_organization_id),'[]'::jsonb),'accounts',coalesce((select jsonb_agg(to_jsonb(a) order by a.code) from public.accounts a where a.organization_id=p_organization_id),'[]'::jsonb),'lines',coalesce((select jsonb_agg(to_jsonb(fl) order by fl.financial_period_id,fl.account_id) from public.forecast_lines fl where fl.organization_id=p_organization_id and fl.planning_version_id=v_version),'[]'::jsonb)) into v_result; return v_result; end; $$;

create or replace function public.get_cash_forecast_workspace(p_organization_id uuid,p_planning_version_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_result jsonb; begin if auth.uid() is null or not public.has_org_permission(p_organization_id,'screen.cash.view') or not public.has_org_permission(p_organization_id,'cash.view') then raise exception 'forbidden'; end if; if not exists(select 1 from public.planning_versions where id=p_planning_version_id and organization_id=p_organization_id and version_type='forecast') then raise exception 'invalid forecast version'; end if; select jsonb_build_object('version',to_jsonb(v),'periods',coalesce((select jsonb_agg(to_jsonb(p) order by p.period_start) from public.financial_periods p where p.organization_id=p_organization_id),'[]'::jsonb),'lines',coalesce((select jsonb_agg(to_jsonb(c) order by c.financial_period_id,c.cash_category) from public.cash_forecast_lines c where c.organization_id=p_organization_id and c.planning_version_id=p_planning_version_id),'[]'::jsonb)) into v_result from public.planning_versions v where v.id=p_planning_version_id; return v_result; end; $$;

create or replace function public.get_scenarios_workspace(p_organization_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ begin if auth.uid() is null or not public.has_org_permission(p_organization_id,'screen.scenarios.view') or not public.has_org_permission(p_organization_id,'scenario.view') then raise exception 'forbidden'; end if; return jsonb_build_object('scenarios',coalesce((select jsonb_agg(to_jsonb(s) order by s.created_at desc) from public.planning_scenarios s where s.organization_id=p_organization_id),'[]'::jsonb),'adjustments',coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at desc) from public.scenario_adjustments a join public.planning_scenarios s on s.id=a.scenario_id where s.organization_id=p_organization_id),'[]'::jsonb),'periods',coalesce((select jsonb_agg(to_jsonb(p) order by p.period_start) from public.financial_periods p where p.organization_id=p_organization_id),'[]'::jsonb),'accounts',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'code',a.code,'name',a.name) order by a.code) from public.accounts a where a.organization_id=p_organization_id),'[]'::jsonb),'base_versions',coalesce((select jsonb_agg(jsonb_build_object('id',v.id,'name',v.name,'version_type',v.version_type,'status',v.status) order by v.created_at desc) from public.planning_versions v where v.organization_id=p_organization_id and v.version_type in ('budget','forecast')),'[]'::jsonb)); end; $$;

create or replace function public.get_variance_analysis(p_organization_id uuid,p_period_id uuid,p_budget_version_id uuid,p_forecast_version_id uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_result jsonb; begin if auth.uid() is null or not public.has_org_permission(p_organization_id,'screen.variance.view') or not public.has_org_permission(p_organization_id,'variance.view') then raise exception 'forbidden'; end if; if not exists(select 1 from public.financial_periods where id=p_period_id and organization_id=p_organization_id) then raise exception 'invalid period'; end if; if not exists(select 1 from public.planning_versions where id=p_budget_version_id and organization_id=p_organization_id and version_type='budget' and status='approved') then raise exception 'budget version must be approved'; end if; if p_forecast_version_id is not null and not exists(select 1 from public.planning_versions where id=p_forecast_version_id and organization_id=p_organization_id and version_type='forecast' and status='approved') then raise exception 'forecast version must be approved'; end if; with actuals as (select ff.account_id,sum(ff.amount_minor)::bigint amount_minor from public.financial_facts ff where ff.organization_id=p_organization_id and ff.financial_period_id=p_period_id and ff.status='published' and public.has_org_data_scope(ff.organization_id,'legal_entity',ff.legal_entity_id) and public.has_org_data_scope(ff.organization_id,'branch',ff.branch_id) and public.has_org_data_scope(ff.organization_id,'department',ff.department_id) and public.has_org_data_scope(ff.organization_id,'cost_center',ff.cost_center_id) and public.has_org_data_scope(ff.organization_id,'region',ff.region_id) and public.has_org_data_scope(ff.organization_id,'product',ff.product_id) and public.has_org_data_scope(ff.organization_id,'project',ff.project_id) group by ff.account_id), budget as (select bl.account_id,sum(bl.amount_minor)::bigint amount_minor from public.budget_lines bl where bl.organization_id=p_organization_id and bl.planning_version_id=p_budget_version_id and bl.financial_period_id=p_period_id group by bl.account_id), forecast as (select fl.account_id,sum(fl.amount_minor)::bigint amount_minor from public.forecast_lines fl where fl.organization_id=p_organization_id and fl.planning_version_id=p_forecast_version_id and fl.financial_period_id=p_period_id group by fl.account_id), rows as (select a.id account_id,a.code,a.name,a.account_type,coalesce(x.amount_minor,0)::bigint actual_minor,coalesce(b.amount_minor,0)::bigint budget_minor,coalesce(f.amount_minor,0)::bigint forecast_minor from public.accounts a left join actuals x on x.account_id=a.id left join budget b on b.account_id=a.id left join forecast f on f.account_id=a.id where a.organization_id=p_organization_id and (x.account_id is not null or b.account_id is not null or f.account_id is not null)) select jsonb_build_object('period_id',p_period_id,'budget_version_id',p_budget_version_id,'forecast_version_id',p_forecast_version_id,'rows',coalesce((select jsonb_agg(jsonb_build_object('account_id',account_id,'code',code,'name',name,'account_type',account_type,'actual_minor',actual_minor,'budget_minor',budget_minor,'forecast_minor',forecast_minor,'variance_vs_budget_minor',actual_minor-budget_minor,'variance_vs_forecast_minor',case when p_forecast_version_id is null then null else actual_minor-forecast_minor end,'variance_vs_budget_pct',case when budget_minor=0 then null else round(((actual_minor-budget_minor)::numeric/abs(budget_minor))*100,2) end) order by code) from rows),'[]'::jsonb)); return v_result; end; $$;

revoke execute on function public.upsert_forecast_line(uuid,uuid,uuid,uuid,bigint,uuid,uuid,uuid,uuid,uuid,uuid,uuid,text),public.delete_forecast_line(uuid,uuid),public.upsert_cash_forecast_line(uuid,uuid,uuid,text,bigint,character,text),public.delete_cash_forecast_line(uuid,uuid),public.create_scenario(uuid,text,text,text,uuid),public.upsert_scenario_adjustment(uuid,uuid,uuid,uuid,text,numeric,text),public.get_forecast_workspace(uuid,uuid),public.get_cash_forecast_workspace(uuid,uuid),public.get_scenarios_workspace(uuid),public.get_variance_analysis(uuid,uuid,uuid,uuid) from anon,public;
grant execute on function public.upsert_forecast_line(uuid,uuid,uuid,uuid,bigint,uuid,uuid,uuid,uuid,uuid,uuid,uuid,text),public.delete_forecast_line(uuid,uuid),public.upsert_cash_forecast_line(uuid,uuid,uuid,text,bigint,character,text),public.delete_cash_forecast_line(uuid,uuid),public.create_scenario(uuid,text,text,text,uuid),public.upsert_scenario_adjustment(uuid,uuid,uuid,uuid,text,numeric,text),public.get_forecast_workspace(uuid,uuid),public.get_cash_forecast_workspace(uuid,uuid),public.get_scenarios_workspace(uuid),public.get_variance_analysis(uuid,uuid,uuid,uuid) to authenticated;